import 'reflect-metadata';
import { Response, NextFunction } from 'express';
import { Container } from 'typedi';
import { AppError } from '@/modules/common/types';
import { getTodayYyyymmdd } from '@/modules/common/utils/dateUtils';
import { BookingService } from '@/modules/bookings/services';
import { AuthRequest } from '@/modules/middleware/auth';
import {
  CancelBookingRequest,
  CreateBookingRequest,
  CreateWellnessPackageBookingRequest,
  CreateSpecialistBookingRequest,
  RescheduleBookingRequest,
  RetryBookingPaymentRequest,
  UpdateBookingRequest,
  BookingQueryParams,
} from '@/modules/bookings/types';

export class BookingController {
  private bookingService: BookingService;

  constructor() {
    this.bookingService = Container.get(BookingService);
  }

  private requireBookingReadActor(req: AuthRequest) {
    const actor = req.user;
    if (
      !actor ||
      typeof actor._id !== 'string' ||
      actor._id.trim().length === 0 ||
      typeof actor.userType !== 'string' ||
      actor.userType.trim().length === 0
    ) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    return actor;
  }

  private resolveHRBookingReadScope(req: AuthRequest): string | undefined {
    if (req.user?.userType !== 'hr') {
      return undefined;
    }

    const corporateId = req.user.corporateId;
    if (
      typeof corporateId !== 'string' ||
      !/^[0-9a-fA-F]{24}$/.test(corporateId)
    ) {
      throw new AppError({
        status: 403,
        code: 'HR_CORPORATE_REQUIRED',
        message: 'HR account must be linked to a corporate',
      });
    }

    const requestedCorporateId = req.query.corporateId;
    const forUser: unknown = req.query.forUser;
    if (
      (requestedCorporateId !== undefined && requestedCorporateId !== corporateId) ||
      (forUser !== undefined && forUser !== false && forUser !== 'false')
    ) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'HR can only access bookings from their own corporate',
      });
    }

    return corporateId;
  }

  private getHRCorporateId(req: AuthRequest): string | undefined {
    return req.user?.userType === 'hr' ? req.user.corporateId : undefined;
  }

  private resolveBookingUserId(req: AuthRequest): string {
    if (req.user?.userType === 'admin') {
      return ((req.body.userId as string | undefined) || req.user!._id);
    }

    if (req.user?.userType === 'pharmacy') {
      const userId = req.body.userId as string | undefined;
      if (!userId) {
        throw new AppError({
          status: 400,
          code: 'USER_ID_REQUIRED',
          message: 'userId is required when a pharmacy creates a booking',
        });
      }

      return userId;
    }

    return req.user!._id;
  }

  private resolveBookingPharmacyId(req: AuthRequest): string | undefined {
    if (req.user?.userType === 'pharmacy') {
      return req.user.pharmacyId || req.user._id;
    }

    if (req.user?.userType === 'admin') {
      return req.body.pharmacyId as string | undefined;
    }

    return undefined;
  }

  private ensureHRReadOnly(req: AuthRequest): void {
    if (req.user?.userType !== 'hr') {
      return;
    }

    throw new AppError({
      status: 403,
      code: 'FORBIDDEN',
      message: 'HR has view-only access to bookings',
    });
  }

  private async ensureHRCanAccessBooking(
    req: AuthRequest,
    bookingId: string
  ): Promise<void> {
    if (req.user?.userType !== 'hr') {
      return;
    }

    const hrCorporateId = this.getHRCorporateId(req);
    if (!hrCorporateId) {
      throw new AppError({
        status: 403,
        code: 'HR_CORPORATE_REQUIRED',
        message: 'HR account must be linked to a corporate',
      });
    }

    const booking = await this.bookingService.getById(bookingId);
    if (booking.corporateId !== hrCorporateId) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'HR can only access bookings from their own corporate',
      });
    }
  }

  createBooking = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    this.ensureHRReadOnly(req);
    const userId = this.resolveBookingUserId(req);

    const data: CreateBookingRequest = {
      ...req.body,
      userId,
      pharmacyId: this.resolveBookingPharmacyId(req),
      corporateId:
        req.user?.userType === 'admin'
          ? req.body.corporateId
          : req.user?.corporateId || req.body.corporateId,
      doctorName:
        (req.body.doctorName as string | undefined) ||
        (req.body.doctor_name as string | undefined),
      packageName:
        (req.body.packageName as string | undefined) ||
        (req.body.package_name as string | undefined),
    };
    const result = await this.bookingService.createBooking(data);

    res.status(201).json({
      success: true,
      message: result.paymentRequired
        ? 'Booking created and payment initiated successfully'
        : 'Booking created successfully',
      data: result,
    });
  };

  createWellnessPackageBooking = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    this.ensureHRReadOnly(req);
    const userId = this.resolveBookingUserId(req);

    const data: CreateWellnessPackageBookingRequest = {
      ...req.body,
      userId,
      pharmacyId: this.resolveBookingPharmacyId(req),
      corporateId:
        req.user?.userType === 'admin'
          ? req.body.corporateId
          : req.user?.corporateId || req.body.corporateId,
      packageName:
        (req.body.packageName as string | undefined) ||
        (req.body.package_name as string | undefined),
    };
    const result = await this.bookingService.createWellnessPackageBooking(data);

    res.status(201).json({
      success: true,
      message: result.paymentRequired
        ? 'Wellness package booking created and payment initiated successfully'
        : 'Wellness package booking created successfully',
      data: result,
    });
  };

  createSpecialistBooking = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    this.ensureHRReadOnly(req);
    const userId = this.resolveBookingUserId(req);

    const data: CreateSpecialistBookingRequest = {
      ...req.body,
      userId,
      pharmacyId: this.resolveBookingPharmacyId(req),
      corporateId:
        req.user?.userType === 'admin'
          ? req.body.corporateId
          : req.user?.corporateId || req.body.corporateId,
      doctorName:
        (req.body.doctorName as string | undefined) ||
        (req.body.doctor_name as string | undefined),
    };
    const result = await this.bookingService.createSpecialistBooking(data);

    res.status(201).json({
      success: true,
      message: result.paymentRequired
        ? 'Specialist booking created and payment initiated successfully'
        : 'Specialist booking created successfully',
      data: result,
    });
  };

  getById = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const actor = this.requireBookingReadActor(req);
    const { id } = req.params;
    if (
      actor.userType === 'user' &&
      req.query.userId !== undefined &&
      req.query.userId !== actor._id
    ) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Access to bookings owned by another user is not permitted',
      });
    }

    await this.ensureHRCanAccessBooking(req, id);
    const userId = actor.userType === 'user'
      ? actor._id
      : req.query.userId as string | undefined;
    const result = await this.bookingService.getById(id, userId);

    res.status(200).json({
      success: true,
      data: result,
    });
  };

  getPaymentDetails = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    const { id } = req.params;
    await this.ensureHRCanAccessBooking(req, id);
    const result = await this.bookingService.getPaymentDetails(id, {
      _id: req.user!._id,
      userType: req.user!.userType,
      corporateId: req.user?.corporateId,
      pharmacyId: req.user?.pharmacyId,
    });

    res.status(200).json({
      success: true,
      data: result,
    });
  };

  getAll = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const requiredCorporateId = this.resolveHRBookingReadScope(req);
    const effectiveUserId =
      req.user?.userType === 'admin'
        ? (req.query.userId as string | undefined)
        : req.user?.userType === 'hr'
          ? (req.query.userId as string | undefined)
        : req.user?.userType === 'pharmacy'
          ? undefined
          : req.user?._id;

    const queryParams: BookingQueryParams = {
      userId: effectiveUserId,
      pharmacyId:
        req.user?.userType === 'pharmacy'
          ? (req.user?.pharmacyId || req.user?._id)
          : (req.query.pharmacyId as string | undefined),
      dependentId: req.query.dependentId as string,
      corporateId:
        this.getHRCorporateId(req) || (req.query.corporateId as string),
      bookingType: req.query.bookingType as
        | 'package'
        | 'consultation'
        | 'second-opinion'
        | 'surgery',
      wellnessPackageId: req.query.wellnessPackageId as string,
      specialistId: req.query.specialistId as string,
      status: req.query.status as any,
      paymentStatus: req.query.paymentStatus as any,
      bookingDateFrom: req.query.bookingDateFrom as string | undefined,
      bookingDateTo: req.query.bookingDateTo as string | undefined,
      page: req.query.page ? parseInt(req.query.page as string) : undefined,
      limit: req.query.limit
        ? parseInt(req.query.limit as string)
        : undefined,
      sortBy: req.query.sortBy as string,
      sortOrder: req.query.sortOrder as 'asc' | 'desc',
      forUser: req.query.forUser === 'true',
    };

    const result = requiredCorporateId === undefined
      ? await this.bookingService.getAll(queryParams)
      : await this.bookingService.getAll(queryParams, requiredCorporateId);

    if (result.total !== undefined) {
      // Paginated response
      res.status(200).json({
        success: true,
        data: result.data,
        pagination: {
          page: result.page!,
          limit: queryParams.limit!,
          total: result.total,
          totalPages: result.totalPages!,
        },
      });
    } else {
      // Non-paginated response
      res.status(200).json({
        success: true,
        data: result.data,
      });
    }
  };

  update = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    this.ensureHRReadOnly(req);
    const { id } = req.params;
    const data: UpdateBookingRequest = req.body;
    const userId = req.query.userId as string | undefined;
    const result = await this.bookingService.update(id, data, userId);

    res.status(200).json({
      success: true,
      message: 'Booking updated successfully',
      data: result,
    });
  };

  delete = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    this.ensureHRReadOnly(req);
    const { id } = req.params;
    const userId = req.query.userId as string | undefined;
    await this.bookingService.delete(id, userId);

    res.status(200).json({
      success: true,
      message: 'Booking deleted successfully',
    });
  };

  getByUserId = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const actor = this.requireBookingReadActor(req);
    const requestedUserId = req.query.userId;
    if (
      actor.userType === 'user' &&
      (req.params.userId !== actor._id ||
        (requestedUserId !== undefined &&
          (typeof requestedUserId !== 'string' ||
            requestedUserId.trim() !== actor._id)))
    ) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Access to bookings owned by another user is not permitted',
      });
    }

    const requiredCorporateId = this.resolveHRBookingReadScope(req);
    const { userId } = req.params;
    const effectiveUserId = actor.userType === 'user' ? actor._id : userId;
    const result =
      req.user?.userType === 'hr'
        ? (
            await this.bookingService.getAll({
              userId,
              corporateId: this.getHRCorporateId(req),
            }, requiredCorporateId)
          ).data
        : await this.bookingService.getByUserId(effectiveUserId);

    res.status(200).json({
      success: true,
      data: result,
    });
  };

  getUpcomingBookings = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    const requiredCorporateId = this.resolveHRBookingReadScope(req);
    if (req.user?.userType === 'hr') {
      const result = await this.bookingService.getAll({
        corporateId: this.getHRCorporateId(req),
        bookingDateFrom: getTodayYyyymmdd(),
      }, requiredCorporateId);

      res.status(200).json({
        success: true,
        data: result.data.filter(
          (booking) => booking.status === 'pending' || booking.status === 'confirmed'
        ),
      });
      return;
    }

    const effectiveUserId =
      req.user?.userType === 'admin'
        ? (req.query.userId as string | undefined)
        : req.user?._id;

    const result = await this.bookingService.getUpcomingBookings(effectiveUserId);

    res.status(200).json({
      success: true,
      data: result,
    });
  };

  retryPayment = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    this.ensureHRReadOnly(req);
    const { id } = req.params;
    const data: RetryBookingPaymentRequest = req.body;
    const result = await this.bookingService.retryBookingPayment(id, {
      _id: req.user!._id,
      userType: req.user!.userType,
      corporateId: req.user?.corporateId,
      pharmacyId: req.user?.pharmacyId,
    }, {
      useWalletBalance: data.useWalletBalance,
      couponCode: data.couponCode,
    });

    res.status(200).json({
      success: true,
      message: result.paymentRequired
        ? 'Booking payment initiated successfully'
        : 'Booking payment completed successfully',
      data: result,
    });
  };

  cancelBooking = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    this.ensureHRReadOnly(req);
    const { id } = req.params;
    const data: CancelBookingRequest = req.body;
    const result = await this.bookingService.cancelBooking(id, data, {
      _id: req.user!._id,
      userType: req.user!.userType,
    });

    res.status(200).json({
      success: true,
      message: 'Booking cancelled successfully',
      data: result,
    });
  };

  rescheduleBooking = async (
    req: AuthRequest,
    res: Response,
    _next: NextFunction
  ) => {
    this.ensureHRReadOnly(req);
    const { id } = req.params;
    const data: RescheduleBookingRequest = req.body;
    const result = await this.bookingService.rescheduleBooking(id, data, {
      _id: req.user!._id,
      userType: req.user!.userType,
    });

    res.status(200).json({
      success: true,
      message: 'Booking rescheduled successfully',
      data: result,
    });
  };
}

import 'reflect-metadata';
import { Router } from 'express';
import { catchAsync } from '@/modules/common/utils/asyncHandler';
import { validate } from '@/modules/common/middleware/validation';
import { BookingController } from '@/modules/bookings/controller';
import {
  cancelBookingSchema,
  createBookingSchema,
  rescheduleBookingSchema,
  createWellnessPackageBookingSchema,
  createSpecialistBookingSchema,
  updateBookingSchema,
  bookingQuerySchema,
  idParamSchema,
  retryPaymentBodySchema,
  userIdParamSchema,
} from '@/modules/bookings/validation';

const bookingRouter = Router();

const bookingController = new BookingController();

// Create wellness package booking
bookingRouter.post(
  '/wellness-package',
  validate(createWellnessPackageBookingSchema, 'body'),
  catchAsync(bookingController.createWellnessPackageBooking)
);

// Create specialist booking
bookingRouter.post(
  '/specialist',
  validate(createSpecialistBookingSchema, 'body'),
  catchAsync(bookingController.createSpecialistBooking)
);

// Unified create booking API
bookingRouter.post(
  '/',
  validate(createBookingSchema, 'body'),
  catchAsync(bookingController.createBooking)
);

// Get all bookings (with optional query params)
// Supports: ?userId=xxx&bookingType=package&status=confirmed&page=1&limit=10
bookingRouter.get(
  '/',
  validate(bookingQuerySchema, 'query'),
  catchAsync(bookingController.getAll)
);

// Get bookings by userId
bookingRouter.get(
  '/user/:userId',
  validate(userIdParamSchema, 'params'),
  catchAsync(bookingController.getByUserId)
);

// Get upcoming bookings
bookingRouter.get(
  '/upcoming',
  validate(bookingQuerySchema, 'query'),
  catchAsync(bookingController.getUpcomingBookings)
);

// Retry payment for an existing booking
bookingRouter.post(
  '/:id/retry-payment',
  validate(idParamSchema, 'params'),
  validate(retryPaymentBodySchema, 'body'),
  catchAsync(bookingController.retryPayment)
);

bookingRouter.post(
  '/:id/cancel',
  validate(idParamSchema, 'params'),
  validate(cancelBookingSchema, 'body'),
  catchAsync(bookingController.cancelBooking)
);

bookingRouter.post(
  '/:id/reschedule',
  validate(idParamSchema, 'params'),
  validate(rescheduleBookingSchema, 'body'),
  catchAsync(bookingController.rescheduleBooking)
);

// Get booking by ID (optionally filter by userId in query)
bookingRouter.get(
  '/:id/payment-details',
  validate(idParamSchema, 'params'),
  catchAsync(bookingController.getPaymentDetails)
);

// Get booking by ID (optionally filter by userId in query)
bookingRouter.get(
  '/:id',
  validate(idParamSchema, 'params'),
  validate(bookingQuerySchema, 'query'),
  catchAsync(bookingController.getById)
);

// Update booking (optionally filter by userId in query)
bookingRouter.put(
  '/:id',
  validate(idParamSchema, 'params'),
  validate(updateBookingSchema, 'body'),
  validate(bookingQuerySchema, 'query'),
  catchAsync(bookingController.update)
);

// Delete booking (optionally filter by userId in query)
bookingRouter.delete(
  '/:id',
  validate(idParamSchema, 'params'),
  validate(bookingQuerySchema, 'query'),
  catchAsync(bookingController.delete)
);

export default bookingRouter;

async getById(id: string, userId?: string): Promise<IBooking> {
  const query: any = { _id: id };

  if (userId) {
    query.userId = userId;
  }

  const booking = await this.bookingRepository.findOne(query);

  if (!booking) {
    throw new AppError({
      status: 404,
      code: 'BOOKING_NOT_FOUND',
      message: 'Booking not found',
    });
  }

  return booking;
}

async getByUserId(userId: string): Promise<IBooking[]> {
  return this.bookingRepository.findByUserId(userId);
}

import { Service } from 'typedi';
import { Model } from 'mongoose';
import BookingModel from '@/modules/bookings/model';
import {
  IBooking,
  BookingQueryParams,
  BookingType,
} from '@/modules/bookings/types';
import { BaseRepository } from '@/modules/common/repository';

@Service()
export class BookingRepository extends BaseRepository<IBooking> {
  constructor() {
    super(BookingModel as Model<IBooking>);
  }

  async getConsultationStatsBySpecialistId(
    specialistId: string,
    options: {
      from?: string;
      to?: string;
    } = {}
  ): Promise<{
    totalAppointments: number;
    totalPatients: number;
    totalUniquePatients: number;

async findByUserId(userId: string): Promise<IBooking[]> {
  return this.findAll(
    { userId },
    { sort: { bookingDate: -1, createdAt: -1 } }
  );
}

import Joi from 'joi';

// Common schemas
const userIdSchema = Joi.string().trim().min(1).required().messages({
  'string.empty': 'User ID is required',
  'any.required': 'User ID is required',
});
const optionalUserIdSchema = Joi.string().trim().min(1).optional().messages({
  'string.empty': 'User ID cannot be empty',
});

export const bookingQuerySchema = Joi.object({
  userId: Joi.string().trim().optional(),
  pharmacyId: Joi.string().pattern(/^[0-9a-fA-F]{24}$/).optional(),
  dependentId: Joi.string().trim().optional(),
  corporateId: Joi.string()
    .pattern(/^[0-9a-fA-F]{24}$/)
    .optional()
    .messages({
      'string.pattern.base': 'Invalid corporate ID format',
    }),
  bookingType: Joi.string()
    .valid('package', 'consultation', 'second-opinion', 'surgery')
    .optional()
    .messages({
      'any.only': 'Booking type must be one of: package, consultation, second-opinion, surgery',
    }),
  wellnessPackageId: Joi.string()
    .pattern(/^[0-9a-fA-F]{24}$/)
    .optional()
    .messages({
      'string.pattern.base': 'Invalid wellness package ID format',
    }),
  specialistId: Joi.string()
    .pattern(/^[0-9a-fA-F]{24}$/)
    .optional()
    .messages({
      'string.pattern.base': 'Invalid specialist ID format',
    }),
  status: Joi.string()
    .valid('pending', 'confirmed', 'completed', 'cancelled')
    .optional()
    .messages({
      'any.only':
        'Status must be one of: pending, confirmed, completed, cancelled',
    }),
  paymentStatus: Joi.string()
    .valid('pending', 'paid', 'failed', 'refunded')
    .optional()
    .messages({
      'any.only':
        'Payment status must be one of: pending, paid, failed, refunded',
    }),
  bookingDateFrom: Joi.string()
    .pattern(/^\d{8}$/)
    .optional()
    .messages({
      'string.pattern.base': 'Booking date from must be in YYYYMMDD format (e.g., 20250215)',
    }),
  bookingDateTo: Joi.string()
    .pattern(/^\d{8}$/)
    .optional()
    .messages({
      'string.pattern.base': 'Booking date to must be in YYYYMMDD format (e.g., 20250215)',
    }),
  page: Joi.number().integer().min(1).optional().messages({
    'number.base': 'Page must be a number',
    'number.integer': 'Page must be an integer',
    'number.min': 'Page must be at least 1',
  }),
  limit: Joi.number().integer().min(1).max(100).optional().messages({
    'number.base': 'Limit must be a number',
    'number.integer': 'Limit must be an integer',
    'number.min': 'Limit must be at least 1',
    'number.max': 'Limit must not exceed 100',
  }),
  sortBy: Joi.string()
    .valid(
      'bookingDate',
      'createdAt',
      'updatedAt',
      'price',
      'status',
      'paymentStatus'
    )
    .optional()
    .messages({
      'any.only':
        'sortBy must be one of: bookingDate, createdAt, updatedAt, price, status, paymentStatus',
    }),
  sortOrder: Joi.string().valid('asc', 'desc').optional().messages({
    'any.only': 'sortOrder must be either "asc" or "desc"',
  }),
  forUser: Joi.string().valid('true', 'false').optional(),
}).custom((value, helpers) => {
  // Validate that bookingDateFrom <= bookingDateTo if both are provided
  if (
    value.bookingDateFrom &&
    value.bookingDateTo &&
    value.bookingDateFrom.localeCompare(value.bookingDateTo) > 0
  ) {
    return helpers.error('any.custom', {
      message: 'Booking date from cannot be greater than booking date to',
    });
  }

  return value;
});

// Params schema for ID
export const idParamSchema = Joi.object({
  id: Joi.string()
    .pattern(/^[0-9a-fA-F]{24}$/)
    .required()
    .messages({
      'string.pattern.base': 'Invalid ID format',
      'any.required': 'ID is required',
    }),
});

// Params schema for userId
export const userIdParamSchema = Joi.object({
  userId: userIdSchema,
});

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { CONFIG } from '@/config/config';
import { AppError } from '@/modules/common/types';
import PharmacyModel from '@/modules/pharmacies/model';

export interface AuthRequest extends Request {
  user?: {
    _id: string;
    phone?: string;
    email?: string;
    corporateId?: string;
    specialistId?: string;
    pharmacyId?: string;
    userType: string;
  };
}

const decodeAuthToken = (authHeader?: string): AuthRequest['user'] | null => {
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }

  const token = authHeader.substring(7);
